import re

from moler.exceptions import ParsingDone

from ta_moler.cmd.shared.fsclish.genericfsclish import GenericcFsclishCommand

__author__ = "Marcin Usielski"
__copyright__ = "Copyright (C) 2020, Nokia"
__email__ = "marcin.usielski@nokia.com"


class ShowNetworkingAclrule(GenericcFsclishCommand):
    """Show networking aclrule command class."""

    def __init__(self, connection, options=None, prompt=None, newline_chars=None, runner=None):
        """
        Show network aclrule command.

        :param connection: moler connection to device, terminal when command is executed.
        :param options: parameters with which the command will be executed
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(ShowNetworkingAclrule, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.options = options
        self._current_rule = None

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "show networking aclrule"
        if self.options:
            cmd = f"{cmd} {self.options}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Parse command output.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_rule(line=line)
                self._parse_data_line(line=line)
            except ParsingDone:
                pass
        return super(ShowNetworkingAclrule, self).on_new_line(line, is_full_line)

    # ACL Rule: 3000
    _re_rule = re.compile(r"Rule\s*:\s*(?P<RULE_ID>\S+)")

    def _parse_rule(self, line):
        """
        Parse line with rule.

        :param line: Line form device.
        :return: None.
        """
        if self._regex_helper.search_compiled(ShowNetworkingAclrule._re_rule, line):
            self._current_rule = self._regex_helper.group("RULE_ID")
            self.current_ret[self._current_rule] = {}
            raise ParsingDone()

    # action      : drop
    # dest addr   : 2a00:8a02:60:1c::1:229/128
    _re_data_line = re.compile(r"\s+(?P<KEY>[^:]+\S)\s*:\s*(?P<VALUE>\S.*\S|\S+)")

    def _parse_data_line(self, line):
        """
        Parse line with data for rule.

        :param line: Line form device.
        :return: None.
        """
        if self._regex_helper.search_compiled(ShowNetworkingAclrule._re_data_line, line):
            key = self._regex_helper.group("KEY")
            value = self._regex_helper.group("VALUE")
            if self._current_rule is not None:
                self.current_ret[self._current_rule][key] = value
                raise ParsingDone()


